import React, { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { ClipboardList, Star, Sparkles, ArrowLeft } from "lucide-react";

function EvaluationTasksPage() {
    const navigate = useNavigate();
    const { studyId } = useParams();

    const [tasks, setTasks] = useState([]);

    useEffect(() => {
        const fetchTasks = async () => {
            const token = localStorage.getItem("token");

            const res = await fetch(`http://localhost:8080/api/studies/${studyId}/evaluation-tasks`, {
                headers: { Authorization: `Bearer ${token}` }
            });

            if (res.ok) {
                const data = await res.json();
                setTasks(data);
            }
        };

        fetchTasks();
    }, [studyId]);

    return (
        <div style={styles.container}>
            <div style={styles.header}>
                <div style={styles.iconTitle}>
                    <ClipboardList size={28} style={{ color: "#06b6d4" }} />
                    <h2 style={styles.title}>Evaluate Artifacts</h2>
                </div>
                <p style={styles.subtitle}>Select an artifact below to start your evaluation.</p>
            </div>

            <div style={styles.grid}>
                {tasks.map((a, index) => (
                    <div key={a.id} style={{ ...styles.card, animationDelay: `${index * 0.1}s` }}>
                        <h3 style={styles.cardTitle}>{a.title}</h3>
                        <p style={styles.cardDesc}>{a.description}</p>

                        <button
                            style={styles.btn}
                            onClick={() => navigate(`/study/${studyId}/tasks/${a.id}`)}
                        >
                            <Sparkles size={16} style={{ marginRight: "6px" }} />
                            Evaluate →
                        </button>
                    </div>
                ))}
            </div>
        </div>
    );
}

const styles = {
    container: {
        minHeight: "100vh",
        background: "linear-gradient(135deg, #0a0a0a 0%, #1a1a2e 50%, #16213e 100%)",
        color: "#fff",
        fontFamily: "'Inter', sans-serif",
        padding: "60px 30px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
    },
    header: {
        textAlign: "center",
        marginBottom: "40px",
    },
    iconTitle: {
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: "10px",
    },
    title: {
        fontSize: "2rem",
        fontWeight: "800",
        background: "linear-gradient(135deg, #06b6d4, #8b5cf6)",
        WebkitBackgroundClip: "text",
        WebkitTextFillColor: "transparent",
    },
    subtitle: {
        color: "rgba(255,255,255,0.6)",
        fontSize: "1rem",
        marginTop: "8px",
    },
    grid: {
        display: "grid",
        gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))",
        gap: "24px",
        width: "100%",
        maxWidth: "1000px",
    },
    card: {
        position: "relative",
        background: "rgba(255,255,255,0.05)",
        borderRadius: "18px",
        padding: "24px",
        border: "1px solid rgba(6,182,212,0.3)",
        backdropFilter: "blur(12px)",
        transition: "all 0.3s ease",
        animation: "slideIn 0.6s ease forwards",
        cursor: "default",
    },
    cardGlow: {
        position: "absolute",
        top: "-40%",
        left: "-40%",
        width: "180%",
        height: "180%",
        background: "radial-gradient(circle, rgba(6,182,212,0.1) 0%, transparent 70%)",
        zIndex: 0,
    },
    cardTitle: {
        fontSize: "1.2rem",
        fontWeight: "700",
        marginBottom: "8px",
    },
    cardDesc: {
        color: "rgba(255,255,255,0.7)",
        fontSize: "0.95rem",
        marginBottom: "20px",
    },
    rating: {
        display: "flex",
        alignItems: "center",
        gap: "6px",
        fontSize: "0.95rem",
        color: "#facc15",
        marginBottom: "16px",
    },
    btn: {
        background: "rgba(6,182,212,0.2)",
        border: "2px solid rgba(6,182,212,0.4)",
        color: "#06b6d4",
        fontWeight: "700",
        padding: "10px 20px",
        borderRadius: "12px",
        cursor: "pointer",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: "100%",
        transition: "all 0.3s ease",
    },
};

export default EvaluationTasksPage;
